wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();

        // A transport failure is a value, not a trap: the report counts
        // characters returned, so a failed fetch reports zero.
        // A request outside the allowlist still traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!(
            "heartbeat at {}: fetched {} characters",
            now.seconds, fetched
        );
        let notified = notifier::notify(&message);

        // The contract is `ensures notified == true`. An output that violates
        // it must not be returned, so a refused notification traps instead.
        if !notified {
            panic!("notifier refused the heartbeat; ensures notified == true cannot hold");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
